 const originalSendChat=sendChat;sendChat=text=>{if(state.mode==='jarvis'&&!isMain()){text=text.trim();if(!text)return;const c=pmCounts(),running=activeProjectRun(),brief=productBrief();state.messages.push({role:'user',mode:'jarvis',text});state.messages.push({role:'assistant',mode:'jarvis',text:project().name+': '+(running?'Eine freigegebene Umsetzung läuft. ':c.approval.length+c.blocked.length?'Du hast '+(c.approval.length+c.blocked.length)+' offene Freigaben oder Rückfragen. ':'Gerade wartet keine Freigabe oder Rückfrage auf dich. ')+'Im Arbeitsvorrat stehen '+c.all.length+' Einträge. Ziel: '+brief.goal,action:{text:'Produktstand ansehen →',path:'projekt/'+state.project}});render();$('#chat-input')?.focus();return;}originalSendChat(text);};
 // One record, three views: roadmap timeline, delivery Kanban and priority lanes.
