 let boardMode='status',draggedItem=null;
 function recordSchedule(f){return schedule[f.id]||null;}
 function timeline(compact=false){const groups=(isMain()?pmMilestones:[{id:'m1',name:'Erste Version'}]).map(m=>({...m,items:pmItems().filter(f=>pmMilestone(f)===m.id)}));return `<div class="timeline-toolbar"><span class="tag">Planungsentwurf · 6 relative Wochen</span><span>Hover für Details · Klick zum Öffnen</span></div><div class="gantt-scroll" tabindex="0" role="region" aria-label="Produkt-Roadmap als Zeitleiste"><div class="gantt-table"><div class="gantt-header"><div>Meilenstein / Eintrag</div><div class="gantt-weeks">${Array.from({length:6},(_,i)=>`<span>Woche ${i+1}</span>`).join('')}</div></div>${groups.map((m,gi)=>{const scheduled=m.items.filter(f=>recordSchedule(f)),end=scheduled.length?Math.max(...scheduled.map(f=>recordSchedule(f).end)):null,done=m.items.filter(f=>pmInfo(f).key==='done').length;return `<section class="gantt-group tone-${gi%3}"><div class="gantt-group-row"><div><strong>${m.name}</strong><small>${done}/${m.items.length} abgenommen</small></div><div class="gantt-grid">${end?`<span class="milestone-line" style="width:${end/6*100}%"></span><span class="milestone-diamond" style="left:calc(${end/6*100}% - 8px)" title="Geplantes Ende des Meilensteins">◇</span>`:''}</div></div>${m.items.map(f=>{const i=pmInfo(f),s=recordSchedule(f);return `<div class="gantt-row"><a class="gantt-label" href="#/arbeit/${f.id}" data-feature-peek="${f.id}"><span>${pmCategory(f).symbol}</span><span>${esc(f.name)}</span><small>${f.priority}</small></a><div class="gantt-grid">${s?`<a class="gantt-bar ${i.key}" style="left:${(s.start-1)/6*100}%;width:${(s.end-s.start+1)/6*100}%" href="#/arbeit/${f.id}" data-feature-peek="${f.id}" aria-label="${esc(f.name)} · Planungswoche ${s.start} bis ${s.end} · ${i.label}"><span class="bar-done" style="width:${i.total?Math.round(i.done/i.total*100):0}%"></span><span>${i.key==='done'?'✓':i.key==='approval'?'◉':i.key==='blocked'?'!':'○'} ${i.label}</span></a>`:button('Zeitfenster planen','edit-schedule','unscheduled-button',`data-id="${f.id}"`)}</div></div>`;}).join('')||'<div class="gantt-empty">Noch keine Einträge zugeordnet.</div>'}</section>`;}).join('')}</div></div><p class="scope">Die Zeitfenster sind ein editierbarer Beispielplan, keine gemessenen Laufzeiten oder zugesagten Termine. Balkenfüllung = abgeschlossene Arbeitsschritte.</p>`;}
 const milestoneRoadmap=pmRoadmap;pmRoadmap=compact=>timeline(compact);
