 function workBrief(f){const i=pmInfo(f),active=i.key==='active',delivered=f.id==='f35'&&!active;return `<section class="execution-brief"><div class="section-label"><h2>Wer macht was – und wofür?</h2>${status(i.label,pmTone(i))}</div><div class="execution-triptych"><div><span class="eyebrow">Zuvor</span><strong>${delivered?'Code Review abgeschlossen':'Auftrag und Umfang klären'}</strong><p>${delivered?'Codex · Code Reviewer':'Product Coach / Router · vorgesehen'}</p></div><div class="execution-current"><span class="eyebrow">Jetzt</span><strong>${i.phase}</strong><p>${i.role}</p><span class="model-label">${active?'Worker: Claude Code · Modell: nicht beobachtet':delivered?'Letzter Worker: Codex · Modell: nicht beobachtet':'Kein Modell aktiv'}</span></div><div><span class="eyebrow">Danach</span><strong>${active?'Unabhängiges Code Review':i.key==='done'?'Nächste Arbeit priorisieren':delivered?'Deine Abnahme / Übergabe':'Umsetzung nach deiner Freigabe'}</strong><p>${active?'Codex · separates Review':i.key==='done'?'Stefan · Produktentscheidung':delivered?'Veröffentlichung bleibt separat':'Claude Code · vorgesehen'}</p></div></div><div class="expected-output"><span class="eyebrow">Erwarteter Output</span><p>${esc(f.criteria||f.benefit||f.description)}</p></div><details><summary>Modellherkunft verstehen</summary><p class="subtle">Claude Code und Codex sind Worker, keine Modellnamen. Das tatsächlich beobachtete Modell ist in diesen Beispieldaten nicht enthalten. Im Produkt wird es aus der Laufakte übernommen, zusammen mit Quelle und Zeitpunkt.</p></details></section>`;}
 const detailedProductItem=featurePage;featurePage=id=>{const f=features.find(x=>x.id===id);const html=detailedProductItem(id);if(!f)return html;return html.replace('<div class="split">',workBrief(f)+'<div class="split">').replace('<h3>Deine Produktplanung</h3>',`<h3>Deine Produktplanung</h3><div class="planning-window"><span>Zeitraum</span><strong>${recordSchedule(f)?'Woche '+recordSchedule(f).start+'–'+recordSchedule(f).end:'Noch nicht geplant'}</strong>${button('Zeitfenster ändern','edit-schedule','button',`data-id="${id}"`)}</div>`);};
 function ring(done,total,label){const pct=total?Math.round(done/total*100):0;return `<div class="progress-bubble" role="img" aria-label="${done} von ${total} ${label}"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="bubble-track" cx="50" cy="50" r="42"/><circle class="bubble-fill" cx="50" cy="50" r="42" pathLength="100" stroke-dasharray="${pct} 100"/></svg><div><strong>${total?pct+' %':'—'}</strong><small>${done}/${total}</small></div></div>`;}
 const portfolioWithoutRings=projectsPage;projectsPage=()=>portfolioWithoutRings().replace(/<article class="panel portfolio-card">/g,()=>'<article class="panel portfolio-card">').replace(/<h2>([^<]+)<\/h2>/g,(match,name)=>{const p=state.projects.find(p=>esc(p.name)===name);if(!p)return match;const fs=features.filter(f=>f.project===p.id),done=fs.filter(f=>pmInfo(f).key==='done').length;return `<div class="portfolio-progress-title"><div>${match}<span class="scope">Erfasste Einträge abgenommen</span></div>${ring(done,fs.length,'Einträgen abgenommen')}</div>`;});
 const priorOverview=overview;overview=()=>{const html=priorOverview();if(!isMain()||state.scenario==='unavailable')return html;const f=features.find(x=>x.id==='f35');return html+`<section class="recent-delivery"><div><div class="eyebrow">Zuletzt umgesetzt</div><h2>Bauen aus der Akte</h2><p>Aus einer vorhandenen Feature-Beschreibung wird ein freigabefähiger Auftrag. Umsetzung und Review sind abgeschlossen.</p>${link(state.accepted?'Abgenommenes Ergebnis ansehen →':'Ergebnis prüfen & abnehmen →','abnahme/f35','button primary')}</div>${ring(state.accepted?3:2,3,'Arbeitsschritten abgeschlossen')}<div class="delivery-next"><span class="eyebrow">Danach</span><p>Priorisiere die nächste Arbeit oder bereite direkt einen Auftrag vor.</p>${link('Arbeitsvorrat priorisieren →','arbeit/prioritaeten','text-link')}</div></section>`;};
 // Status transitions are controlled by actual execution and approval; prioritization is editable.
 const statusBoard=pmBoard;pmBoard=selected=>`<div class="view-switch">${link('Kanban · Status','arbeit/board',boardMode==='status'?'active':'')}${link('Kanban · Priorität','arbeit/prioritaeten',boardMode==='priority'?'active':'')}${link('Zeitleiste','projekt/'+state.project+'/roadmap','')}</div>`+(boardMode==='priority'?priorityBoard():statusBoard(selected).replaceAll('Entwicklungsboard','Kanban'));
 function boardRecord(f){const i=pmInfo(f);return `<article class="priority-card" draggable="true" data-drag-item="${f.id}"><div class="board-item-meta"><span>${pmCategory(f).symbol} ${pmCategory(f).singular}</span><span class="drag-grip" aria-hidden="true">⠿</span></div><a href="#/arbeit/${f.id}" data-feature-peek="${f.id}"><h3>${esc(f.name)}</h3></a>${status(i.label,pmTone(i))}<div class="card-quick-actions"><label>Priorität<select data-item-priority="${f.id}" aria-label="Priorität für ${esc(f.name)}">${['P0','P1','P2','P3'].map(p=>`<option ${p===f.priority?'selected':''}>${p}</option>`).join('')}</select></label>${i.key==='planned'?button('Umsetzung vorbereiten','pm-prepare','button',`data-id="${f.id}"`):link(i.next+' →',i.path,'button')}</div></article>`;}
 function priorityBoard(){return `<p class="scope">Ziehe Karten zwischen Prioritäten oder nutze ihre Auswahlfelder. Priorisieren startet keine Ausführung.</p><div class="priority-board">${[['P0','Kritisch'],['P1','Hoch'],['P2','Normal'],['P3','Später']].map(([p,n])=>`<section class="priority-lane" data-drop-priority="${p}"><div class="board-column-title"><h2>${p} · ${n}</h2><span>${pmItems().filter(f=>f.priority===p).length}</span></div>${pmItems().filter(f=>f.priority===p).map(boardRecord).join('')||'<div class="board-empty">Keine Einträge</div>'}</section>`).join('')}</div>`;}
 const workWithCategories=workPage;workPage=(tab='board')=>{boardMode=tab==='prioritaeten'?'priority':'status';return workWithCategories(tab==='prioritaeten'?'board':tab).replace('Entwicklungsboard','Kanban-Board');};
 const rowWithoutQuickActions=pmStatusRow;pmStatusRow=f=>{const i=pmInfo(f);return `<div class="work-action-line">${rowWithoutQuickActions(f)}<div class="inline-row-actions"><select data-item-priority="${f.id}" aria-label="Priorität für ${esc(f.name)}">${['P0','P1','P2','P3'].map(p=>`<option ${p===f.priority?'selected':''}>${p}</option>`).join('')}</select>${i.key==='planned'?button('Vorbereiten','pm-prepare','button',`data-id="${f.id}"`):link(i.next,i.path,'button')}</div></div>`;};
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action="edit-schedule"]');if(!el)return;const f=features.find(x=>x.id===el.dataset.id);if(!f)return;const s=recordSchedule(f)||{start:1,end:1};modal('Zeitfenster planen',`<form id="schedule-plan" data-id="${f.id}"><h3>${esc(f.name)}</h3><p class="subtle">Relative Wochen im Planungsentwurf. Keine verbindliche Schätzung der Workforce.</p><div class="grid cols-2"><label class="field">Startwoche<select name="start">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${s.start===n?'selected':''}>Woche ${n}</option>`).join('')}</select></label><label class="field">Endwoche<select name="end">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${s.end===n?'selected':''}>Woche ${n}</option>`).join('')}</select></label></div><div class="dialog-actions">${button('Abbrechen','close-modal')}<button type="submit" class="button primary">Planung speichern</button></div></form>`);});
 document.addEventListener('submit',e=>{if(e.target.id!=='schedule-plan')return;e.preventDefault();const d=new FormData(e.target),start=Number(d.get('start')),end=Number(d.get('end'));if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end>6||start>end){toast('Das Ende muss in oder nach der Startwoche liegen.');return;}schedule[e.target.dataset.id]={start,end};closeModal();render();toast('Zeitfenster im Planungsentwurf aktualisiert.');});
 document.addEventListener('change',e=>{if(!e.target.dataset.itemPriority)return;const f=features.find(x=>x.id===e.target.dataset.itemPriority);if(f&&['P0','P1','P2','P3'].includes(e.target.value)){f.priority=e.target.value;render();toast('Priorität aktualisiert.');}});
 document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag-item]');if(!el)return;draggedItem=el.dataset.dragItem;e.dataTransfer.setData('text/plain',draggedItem);e.dataTransfer.effectAllowed='move';hidePeek();});
