 const overviewWithDeliveries=overview;overview=()=>{const html=overviewWithDeliveries();if(state.scenario==='unavailable')return html;const c=pmCounts(),f=c.active[0]||c.approval[0]||c.blocked[0]||c.planned[0];if(!f)return html;return html.replace('<section class="recent-delivery">',`<div class="overview-execution">${workBrief(f)}</div><section class="recent-delivery">`)+(isMain()?'':`<div class="overview-execution">${workBrief(f)}</div>`);};
 const oldShell=shell;shell=()=>{oldShell();const path=(location.hash.slice(2)||'uebersicht').split('/');const nav=$('#sidebar nav');if(nav)nav.innerHTML=[['uebersicht','home','Produktübersicht'],['projekte','folder','Alle Produkte'],['roadmap','work','Roadmap'],['arbeit','chart','Entwicklung'],['entscheidungen','alert','Entscheidungen'],['harness','spark','Workforce']].map(([key,i,n])=>`<a href="#/${key==='roadmap'?'projekt/'+state.project+'/roadmap':key}" data-nav="${key}">${icon(i)}${n}</a>`).join('');const top=$('#topbar');if(top){const persona=state.scenario==='unavailable'?'Status unbekannt':activeProjectRun()?'Arbeitet für dich':pmCounts().approval.length||pmCounts().blocked.length?'Wartet auf dich':'Bereit für deine Idee';top.insertAdjacentHTML('beforeend',`<button class="persona-button" data-action="toggle-chat" aria-label="Jarvis öffnen – ${persona}"><img class="persona-portrait" src="assets/face.png" alt="Jarvis – Augen und Grinsen"><span>${persona}</span></button>`);}const actions=$('#topbar .top-right');if(actions)actions.insertAdjacentHTML('afterbegin',button(ui.theme==='light'?'☾':'☼','toggle-theme','icon-button theme-toggle',`aria-label="${ui.theme==='light'?'Dunkles':'Helles'} Design aktivieren" title="Hell / Dunkel"`));};
 function applyTheme(){document.documentElement.dataset.theme=ui.theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',ui.theme==='light'?'#f3f1e9':'#10212b');}
 let observer;
 function setupSkeleton(){observer?.disconnect();if(!(location.hash==='#/harness'||location.hash.includes('harness/skelett'))||!('IntersectionObserver'in window))return;observer=new IntersectionObserver(entries=>{const hit=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(hit){ui.module=hit.target.dataset.module;$$('.skeleton-node').forEach(n=>n.classList.toggle('selected',n.dataset.id===ui.module));}},{rootMargin:'-20% 0px -45% 0px',threshold:[0,.2,.5]});$$('[data-module]').forEach(n=>observer.observe(n));}
 function chatDock(){let root=$('#chat-dock');if(!root){root=document.createElement('div');root.id='chat-dock';document.body.appendChild(root);}const full=location.hash.startsWith('#/jarvis');if(full){root.innerHTML=button('↙ Gespräch verkleinern','shrink-chat','button chat-shrink');return;}root.innerHTML=`${ui.chat?`<section class="chat-popover" aria-label="Gespräch mit Jarvis"><div class="chat-popover-header"><div><strong>${state.mode==='coach'?'Product Coach':'Jarvis'}</strong><small>${esc(project().name)}</small></div><div class="inline">${button('↗','expand-chat','icon-button','aria-label="Gespräch groß öffnen" title="Vergrößern"')}${button(icon('close'),'close-chat','icon-button','aria-label="Chat schließen"')}</div></div><div class="dock-tabs">${button('Jarvis','dock-mode',state.mode==='jarvis'?'active':'','data-mode="jarvis"')}${button('Product Coach','dock-mode',state.mode==='coach'?'active':'','data-mode="coach"')}</div><div class="dock-messages" tabindex="0" aria-label="Gesprächsverlauf">${state.messages.filter(m=>m.mode===state.mode).length?state.messages.filter(m=>m.mode===state.mode).map(m=>`<div class="message ${m.role}">${m.role==='assistant'?'<div class="eyebrow">Beispielantwort</div>':''}${esc(m.text).replace(/\n/g,'<br>')}${m.action?`<p>${link(m.action.text,m.action.path,'text-link')}</p>`:''}</div>`).join(''):`<div class="dock-intro"><img src="assets/face.png" alt=""><h3>${state.mode==='coach'?'Welche Idee nehmen wir uns vor?':'Was möchtest du wissen?'}</h3><p>Wir bleiben im Kontext von ${esc(project().name)}.</p>${button(state.mode==='coach'?'Eine Feature-Idee schärfen':'Was braucht mich?','prompt','button',`data-text="${state.mode==='coach'?'Eine Feature-Idee schärfen':'Was braucht mich?'}"`)}</div>`}${state.mode==='coach'&&state.chatDraft?`<div class="note"><strong>Dein Entwurf ist bereit.</strong><p>${esc(state.chatDraft.title)}</p>${button('Als Auftrag anlegen','coach-to-task','button primary')}</div>`:''}</div><form id="chat-form" class="dock-composer"><label class="sr-only" for="chat-input">Deine Nachricht</label><textarea id="chat-input" name="message" placeholder="Deine Nachricht …" required></textarea><button class="button primary" type="submit" aria-label="Nachricht senden">${icon('send')}</button></form><div class="dock-disclaimer">Designvorschau · keine KI-Verbindung</div></section>`:''}<button class="chat-bubble" data-action="toggle-chat" aria-expanded="${ui.chat}" aria-label="${ui.chat?'Chat schließen':'Chat mit Jarvis öffnen'}">${ui.chat?icon('close'):'<img class="bubble-persona" src="assets/face.png" alt="">'}<span>${ui.chat?'Schließen':'Frag Jarvis'}</span></button>`;const msgs=$('.dock-messages');if(msgs)msgs.scrollTop=msgs.scrollHeight;}
 let peekTimer,hideTimer,peekOrigin,suppressPeekFocus=false;
 function hidePeek(){clearTimeout(peekTimer);clearTimeout(hideTimer);$('#feature-peek')?.remove();ui.peek=null;}
 function showPeek(el){const f=features.find(x=>x.id===el.dataset.featurePeek);if(!f)return;clearTimeout(hideTimer);if(ui.peek===f.id)return;hidePeek();ui.peek=f.id;peekOrigin=el;const p=featureState(f.id),box=document.createElement('section');box.id='feature-peek';box.className='feature-peek';box.setAttribute('role','dialog');box.setAttribute('aria-label','Feature-Vorschau: '+f.name);box.innerHTML=`<div class="inline" style="justify-content:space-between"><span class="eyebrow">${pmCategory(f).singular} · ${pmFeatureLabel(f)}</span>${button(icon('close'),'close-peek','icon-button','aria-label="Vorschau schließen"')}</div><h3>${f.name}</h3><p>${f.description}</p>${status(p.label,p.label==='Abnahme offen'?'amber':'neutral')}<div class="peek-role"><span>Gerade dran</span><strong>${p.role}</strong></div>${progressBar(p,true)}<div class="action-row">${link('Details öffnen →','arbeit/'+f.id,'button primary')}${p.key==='approval'||p.key==='blocked'?link(p.next,p.path,'button'):''}</div>`;document.body.appendChild(box);const r=el.getBoundingClientRect();box.style.left=Math.max(12,Math.min(r.left,innerWidth-box.offsetWidth-12))+'px';const below=innerHeight-r.bottom,above=r.top;box.style.top=Math.max(12,Math.min(below>=box.offsetHeight+15?r.bottom+9:above>=box.offsetHeight+15?r.top-box.offsetHeight-9:12,innerHeight-box.offsetHeight-12))+'px';box.addEventListener('pointerenter',()=>clearTimeout(hideTimer));box.addEventListener('pointerleave',()=>{hideTimer=setTimeout(hidePeek,250);});}
 function decorateFeatures(){$$('#main a[href]').forEach(a=>{const m=a.getAttribute('href').match(/^#\/(?:arbeit|abnahme)\/([^/]+)$/);if(m&&features.some(f=>f.id===m[1])){a.dataset.featurePeek=m[1];a.setAttribute('aria-haspopup','dialog');}});}
 const oldRender=render;render=()=>{hidePeek();const path=(location.hash.slice(2)||'uebersicht').split('/');if(path[0]==='harness'){shell();$('#main').innerHTML=harnessPage(path[1]||'skelett');$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav==='harness');if(a.dataset.nav==='harness')a.setAttribute('aria-current','page');});document.title='Harness · AI Workforce';document.body.classList.remove('menu-open');}else oldRender();const selected=path[0]==='entscheidungen'?'entscheidungen':path[0]==='faehigkeiten'||path[0]==='faehigkeit'?'harness':path[0]==='projekt'&&path[2]==='roadmap'?'roadmap':path[0]==='projekt'&&path[1]!=='neu'?'uebersicht':null;if(selected)$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===selected);if(a.dataset.nav===selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});applyTheme();decorateFeatures();setupSkeleton();chatDock();};
 document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-feature-peek]');if(el&&!el.contains(e.relatedTarget)){clearTimeout(hideTimer);clearTimeout(peekTimer);peekTimer=setTimeout(()=>showPeek(el),600);}});
 document.addEventListener('pointerout',e=>{const el=e.target.closest('[data-feature-peek]');if(el&&!el.contains(e.relatedTarget)){clearTimeout(peekTimer);hideTimer=setTimeout(hidePeek,250);}});
 document.addEventListener('focusin',e=>{if(suppressPeekFocus){suppressPeekFocus=false;return;}const el=e.target.closest('[data-feature-peek]');if(el)showPeek(el);else if(!e.target.closest('#feature-peek'))hidePeek();});
 document.addEventListener('keydown',e=>{if(e.altKey&&e.key==='ArrowDown'){const origin=e.target.closest('[data-feature-peek]');if(origin){e.preventDefault();showPeek(origin);$('#feature-peek button')?.focus();}}if(e.key==='Escape'){const was=ui.peek;hidePeek();if(was){suppressPeekFocus=true;peekOrigin?.focus();}else if(ui.chat){ui.chat=false;chatDock();$('.chat-bubble')?.focus();}}});
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case'toggle-theme':ui.theme=ui.theme==='light'?'dark':'light';storeWrite('jarvis-theme',ui.theme);render();break;case'set-theme':ui.theme=el.dataset.theme;storeWrite('jarvis-theme',ui.theme);render();break;case'toggle-chat':ui.chat=!ui.chat;chatDock();if(ui.chat)$('#chat-input')?.focus();break;case'close-chat':ui.chat=false;chatDock();$('.chat-bubble')?.focus();break;case'dock-mode':state.mode=el.dataset.mode;chatDock();break;case'expand-chat':ui.lastRoute=location.hash.slice(2)||'uebersicht';ui.chat=false;go(state.mode==='coach'?'jarvis/coach':'jarvis');break;case'shrink-chat':ui.chat=true;go(ui.lastRoute);break;case'select-phase':ui.phase=el.dataset.id;$('#phase-inspector').innerHTML=phaseDetail(ui.phase);$$('.phase-node').forEach(n=>{n.classList.toggle('selected',n.dataset.id===ui.phase);n.setAttribute('aria-pressed',String(n.dataset.id===ui.phase));});break;case'inspect-project':activateProduct(el.dataset.id);ui.phase=null;state.messages=[];state.chatDraft=null;state.taskDraft=null;go('harness/phasen');break;case'inspect-module':ui.module=el.dataset.id;$('#module-'+ui.module)?.scrollIntoView({behavior:state.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'instant',block:'center'});$$('.skeleton-node').forEach(n=>n.classList.toggle('selected',n.dataset.id===ui.module));break;case'edit-module':case'edit-phase':{const phase=el.dataset.action==='edit-phase',m=(phase?phases:modules).find(x=>x.id===el.dataset.id),key=(phase?'phase-':'')+m.id,d=ui.drafts[key];modal('Design bearbeiten · '+m.title,`<form id="harness-edit" data-key="${key}"><div class="note">Diese Änderungen betreffen nur deinen Designentwurf. Rollenverträge, Freigaben und laufende Arbeit bleiben unverändert.</div><label class="field">Aufgabe / Beschreibung<textarea name="description" required minlength="8">${esc(d?.description||m.desc)}</textarea></label><label class="field">Erwartetes Ergebnis<textarea name="output" required minlength="5">${esc(d?.output||m.output)}</textarea></label><div class="dialog-actions">${button('Abbrechen','close-modal')}<button type="submit" class="button primary">Designentwurf speichern</button></div></form>`);break;}case'close-peek':hidePeek();break;}});
 document.addEventListener('submit',e=>{if(e.target.id==='start-permission'&&state.runActive){state.activeProject=state.project;render();}if(e.target.id!=='harness-edit')return;e.preventDefault();const data=new FormData(e.target);ui.drafts[e.target.dataset.key]={description:data.get('description').trim(),output:data.get('output').trim()};storeWrite('jarvis-harness-design',ui.drafts);closeModal();render();toast('Designentwurf in diesem Browser gespeichert.');});
 // A tap opens the same preview that appears on hover; its button opens the page.
