 // Product management lifecycle, revision-safe editing and evidence-led insights.
 const cycleSteps=[
 ['strategy','Strategie','Vision, Zielgruppe und messbaren Nutzen klären.','Produktbriefing'],
 ['discover','Nutzer verstehen','Interviews, Beobachtungen und offene Nutzerfragen festhalten.','Nutzerforschung'],
 ['capture','Feedback sammeln','Rückmeldungen mit Quelle und betroffenen Einträgen verbinden.','Feedback'],
 ['explore','Lösungen erkunden','Alternativen, Annahmen und Experimente vergleichen.','Lösungsideen'],
 ['plan','Planen','Features priorisieren und Meilensteinen zuordnen.','Roadmap'],
 ['showcase','Ausrichtung teilen','Roadmap, Nutzen und nächste Lieferung verständlich vermitteln.','Produktkommunikation'],
 ['deliver','Entwickeln','Umsetzung, Review und menschliche Abnahme steuern.','Entwicklung'],
 ['document','Dokumentieren','Produktwissen, Entscheidungen und Änderungen festhalten.','Produktwissen'],
 ['launch','Veröffentlichen','Release vorbereiten und bewusst zur Veröffentlichung freigeben.','Releaseplanung'],
 ['analyze','Wirkung prüfen','Ergebnisse mit Produktzielen und Nutzerfeedback vergleichen.','Wirkungsmessung']
 ];
 const cycleNotes={},insightNotes={},revisionHistory={};
 const tx=s=>window.JarvisI18n?window.JarvisI18n.t(s):s;
 function productCockpit(){const c=pmCounts(),f=c.active[0]||c.approval[0]||c.blocked[0],i=f?pmInfo(f):null,active=activeProjectRun();return `<section class="product-cockpit"><article class="cockpit-progress">${ring(c.done.length,c.all.length,'Einträgen abgenommen')}<div><span class="eyebrow">Produktfortschritt</span><h2>${c.done.length} / ${c.all.length} <span>abgenommen</span></h2><p>Erfasste Einträge · keine Aufwandsprognose</p>${link('Entwicklungsstand ansehen →','arbeit/board','text-link')}</div></article><article class="cockpit-role"><span class="eyebrow">Aktuelle Rolle</span><h2>${active?'Builder':i?i.phase:'Noch keine Rolle aktiv'}</h2><p>${active?'Claude Code':i?i.role:'Nächste Arbeit planen'}</p><small>${active?'Modell: nicht beobachtet':i?'Menschliche Entscheidung · kein Modell aktiv':'Keine aktive Ausführung'}</small>${f?link(esc(f.name)+' →','arbeit/'+f.id,'text-link'):link('Arbeit priorisieren →','arbeit/prioritaeten','text-link')}</article><article class="cockpit-deployer"><span class="eyebrow">Deployer · Mensch</span><h2>${c.approval.length?'Deine Freigabe':c.done.length?'Übergabe planen':'Noch nicht bereit'}</h2><p>Stefan · Abnahme und Veröffentlichung</p><small>Abgenommen heißt noch nicht veröffentlicht.</small>${link(c.approval.length?'Ergebnisse prüfen →':'Phasen & Rollen ansehen →',c.approval.length?'entscheidungen':'harness/phasen','text-link')}</article></section>`;}
 const v5Overview=overview;overview=()=>{let html=v5Overview();if(state.scenario==='unavailable')return html;html=html.replace(/<section class="product-brief-strip">[\s\S]*?<\/section>/,'');html=html.replace('<div class="pm-summary-strip">',productCockpit()+'<div class="pm-summary-strip">');return html.replace('<div class="pm-focus-layout">',briefStrip()+`<a class="cycle-entry" href="#/produktzyklus/strategy"><div><span class="eyebrow">Produktmanagement</span><strong>Von der Vision zur messbaren Wirkung</strong><p>Strategie · Nutzerwissen · Planung · Entwicklung · Veröffentlichung · Lernen</p></div><span>Produktzyklus öffnen →</span></a><div class="pm-focus-layout">`);};
 function cyclePage(step='strategy'){const s=cycleSteps.find(x=>x[0]===step)||cycleSteps[0],notes=cycleNotes[state.project]?.[s[0]]||[];let body='';if(s[0]==='strategy')body=briefStrip();else if(s[0]==='plan')body=`${link('Priorisieren →','arbeit/prioritaeten','button primary')}${pmRoadmap(true)}`;else if(s[0]==='deliver')body=productCockpit()+link('Kanban öffnen →','arbeit/board','button primary');else if(s[0]==='showcase')body=`<div class="note"><h3>${esc(project().name)}</h3><p>${esc(productBrief().goal)}</p><p>${pmCounts().done.length} / ${pmItems().length} <span>abgenommen</span></p>${link('Roadmap ansehen →','projekt/'+state.project+'/roadmap','text-link')}</div>`;else if(s[0]==='launch')body=`<div class="note"><h3>Release prüfen</h3><p>Abnahme, Dokumentation und Veröffentlichung werden getrennt geprüft.</p><ul><li>Akzeptanzkriterien erfüllt?</li><li>Review und Abnahme dokumentiert?</li><li>Releasehinweise und Rückfallplan vorhanden?</li></ul>${link('Ergebnisse prüfen →','entscheidungen','button')}</div>`;else if(s[0]==='analyze')body=`<div class="note"><span class="eyebrow">Erfolgskriterium aus dem Produktbriefing</span><p>${esc(productBrief().success)}</p><strong>Noch keine Wirkungsmessung erfasst.</strong><p>Abgeschlossene Features belegen noch keinen Nutzernutzen.</p></div>`;return heading('Produktmanagement',tx(s[1]),tx(s[2]))+`<nav class="cycle-nav" aria-label="Produktzyklus">${cycleSteps.map((x,i)=>link(`<small>${String(i+1).padStart(2,'0')}</small><span>${tx(x[1])}</span>`,'produktzyklus/'+x[0],x[0]===s[0]?'active':'')).join('')}</nav><section class="cycle-content">${body}<div class="section-label"><h2>${tx(s[3])}</h2>${button('Notiz hinzufügen','cycle-note','button primary',`data-step="${s[0]}"`)}</div><div class="cycle-notes">${notes.map(n=>`<article class="insight-card"><span class="tag">${esc(n.kind)}</span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><small>${esc(n.source)}</small>${n.item?link('Verknüpften Eintrag öffnen →','arbeit/'+n.item,'text-link'):''}</article>`).join('')||'<p class="subtle">Noch keine Erkenntnisse oder Entscheidungen erfasst.</p>'}</div><p class="scope">Sitzungsentwurf · keine Live-Daten oder automatische Veröffentlichung.</p></section>`;}
 function insightsPanel(f){const i=pmInfo(f),notes=insightNotes[f.id]||[];return `<section class="item-insights"><div class="section-label"><h2>Insights & Erkenntnisse</h2>${button('Insight hinzufügen','add-insight','button',`data-id="${f.id}"`)}</div><div class="insight-grid"><article class="insight-card"><span class="tag">Beobachtung · Vorschauzustand</span><h3>${i.label}</h3><p>${esc(f.description)}</p><small>Quelle: Eintrag und aktueller Ablaufstatus</small></article><article class="insight-card"><span class="tag">Offene Frage · keine Diagnose</span><h3>${f.category==='bugs'?'Ursache und Auswirkung klären':'Nutzen und Annahmen prüfen'}</h3><p>${f.category==='bugs'?'Wie lässt sich der Fehler reproduzieren? Wer ist betroffen? Welche Nachweise stützen die vermutete Ursache?':'Welche Nutzer brauchen das? Welches Problem wird gelöst? Woran lässt sich die Verbesserung messen?'}</p>${button('Mit Product Coach besprechen','insight-coach','button',`data-id="${f.id}"`)}</article>${notes.map(n=>`<article class="insight-card"><span class="tag">${esc(n.kind)}</span><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><small>${esc(n.source)}</small></article>`).join('')}</div><p class="scope">Keine automatische KI-Analyse. Erkenntnisse und Quellen werden von dir ergänzt.</p></section>`;}
 const v5Feature=featurePage;featurePage=id=>{const f=features.find(x=>x.id===id);let html=v5Feature(id);if(!f)return html;return html.replace('<div class="pm-detail-status">',`<div class="feature-edit-actions">${button('Eintrag bearbeiten','edit-item','button',`data-id="${id}"`)}${button('Insights ansehen','focus-insights','button',`data-id="${id}"`)}${f.parentId?link('Ursprünglichen Eintrag ansehen →','arbeit/'+f.parentId,'text-link'):''}</div><div class="pm-detail-status">`)+insightsPanel(f)+(revisionHistory[id]?.length?`<details class="revision-history"><summary>Änderungsverlauf</summary>${revisionHistory[id].map(r=>`<p><strong>${esc(r.reason)}</strong><br>${esc(r.before.name)} · ${esc(r.date)}</p>`).join('')}</details>`:'');};
 function noteForm(kind,id){const isCycle=kind==='cycle',items=pmItems();modal(isCycle?'Produktwissen festhalten':'Insight hinzufügen',`<form id="${isCycle?'cycle-note-form':'insight-form'}" data-id="${esc(id)}"><label class="field">Einordnung<select name="kind"><option value="Beobachtung">Beobachtung</option><option value="Hypothese">Hypothese</option><option value="Feedback">Feedback</option><option value="Entscheidung">Entscheidung</option><option value="Messwert">Messwert</option></select></label><label class="field">Titel<input name="title" required maxlength="120"></label><label class="field">Erkenntnis<textarea name="text" required></textarea></label><label class="field">Quelle oder Nachweis<input name="source" required placeholder="Interview, Fehlermeldung, Test oder Beobachtung …"></label>${isCycle?`<label class="field">Verknüpfter Eintrag<select name="item"><option value="">Kein Eintrag</option>${items.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></label>`:''}<p class="scope">Sitzungsentwurf · keine automatische KI-Analyse.</p><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Speichern</button></div></form>`);}
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const f=features.find(x=>x.id===el.dataset.id);switch(el.dataset.action){case'cycle-note':noteForm('cycle',el.dataset.step);break;case'add-insight':if(f)noteForm('insight',f.id);break;case'focus-insights':document.querySelector('.item-insights')?.scrollIntoView({behavior:state.motion?'smooth':'auto',block:'start'});break;case'insight-coach':if(f){state.mode='coach';ui.chat=true;chatDock();const input=$('#chat-input');if(input){input.value=tx('Bitte hinterfrage diesen Eintrag:')+' '+f.name+'\n'+f.description;input.focus();}}break;case'edit-item':if(f){const revision=pmInfo(f).key!=='planned';modal('Eintrag bearbeiten',`<form id="edit-item-form" data-id="${f.id}"><p class="note">${revision?'Dieser Eintrag wurde bereits gestartet oder geprüft. Deine Änderung wird als neue, verknüpfte Fassung angelegt. Bestehende Arbeit und Freigaben bleiben nachvollziehbar.':'Titel, Beschreibung und Akzeptanzkriterien direkt aktualisieren.'}</p><label class="field">Titel<input name="name" value="${esc(f.name)}" required maxlength="120"></label><label class="field">Beschreibung<textarea name="description" required>${esc(f.description)}</textarea></label><label class="field">Akzeptanzkriterien<textarea name="criteria" required>${esc(f.criteria||(f.id==='f35'?'Ein Auftrag lässt sich aus einer Feature-Datei vorbereiten. Kein schreibender Schritt startet ohne Freigabe.':''))}</textarea></label><label class="field">Änderungsgrund<textarea name="reason" required placeholder="Was ist veraltet oder hat sich geändert?"></textarea></label><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">${revision?'Änderungsfassung anlegen':'Änderungen speichern'}</button></div></form>`);}break;}});
 document.addEventListener('submit',e=>{const form=e.target;if(!['edit-item-form','cycle-note-form','insight-form'].includes(form.id))return;e.preventDefault();const d=new FormData(form),read=k=>String(d.get(k)||'').trim();if(form.id==='edit-item-form'){const f=features.find(x=>x.id===form.dataset.id);if(!f||!['name','description','criteria','reason'].every(k=>read(k)))return;const before={name:f.name,description:f.description,criteria:f.criteria||''},reason=read('reason'),date=new Date().toISOString();let target=f;if(pmInfo(f).key!=='planned'){target={...f,id:'item-'+pm.serial++,parentId:f.id,custom:true,status:'Geplant'};features.push(target);pm.milestones[target.id]=pmMilestone(f);}Object.assign(target,{name:read('name'),description:read('description'),criteria:read('criteria')});(revisionHistory[target.id]??=[]).push({before,reason,date});closeModal();go('arbeit/'+target.id);toast('Änderung gespeichert. Keine Ausführung gestartet.');return;}if(!['title','text','source'].every(k=>read(k)))return;const n={title:read('title'),text:read('text'),source:read('source'),kind:read('kind'),item:read('item')};if(form.id==='cycle-note-form'){const map=cycleNotes[state.project]??={};(map[form.dataset.id]??=[]).push(n);if(n.item)(insightNotes[n.item]??=[]).push({...n});}else(insightNotes[form.dataset.id]??=[]).push(n);closeModal();render();toast('Erkenntnis mit Quelle gespeichert.');});
 const v6Shell=shell;shell=()=>{v6Shell();$('#sidebar nav')?.insertAdjacentHTML('beforeend',link(icon('work')+'Produktzyklus','produktzyklus/strategy',''));$('#topbar .top-right')?.insertAdjacentHTML('afterbegin',`<label class="language-picker"><span class="sr-only">Sprache</span><select id="language-select" aria-label="Sprache">${[['de','Deutsch'],['en','English'],['tr','Türkçe'],['ru','Русский']].map(([id,n])=>`<option value="${id}" ${window.JarvisI18n?.language===id?'selected':''}>${n}</option>`).join('')}</select></label>`);};
 const v6Render=render;render=()=>{v6Render();if(location.hash.startsWith('#/produktzyklus')){$('#main').innerHTML=cyclePage(location.hash.split('/')[2]);document.title=tx('Produktmanagement')+' · AI Workforce';}window.JarvisI18n?.translate();};
 document.addEventListener('change',e=>{if(e.target.id==='language-select'&&window.JarvisI18n){window.JarvisI18n.set(e.target.value);render();}});

 // Final entrance and secondary navigation placement.
 const entranceShell=shell;shell=()=>{entranceShell();const nav=$('#sidebar nav'),bottom=$('#sidebar .side-bottom');nav?.querySelector('[data-nav="projekte"]')?.remove();nav?.querySelector('[data-nav="harness"]')?.remove();if(bottom){bottom.insertAdjacentHTML('afterbegin',link(icon('folder')+'Alle Produkte','projekte','secondary-products'));bottom.insertAdjacentHTML('beforeend',link(icon('spark')+'Workforce','harness/skelett','secondary-workforce'));}const brand=$('#sidebar .brand');if(brand)brand.setAttribute('href','#/start');};
 function entrance(){return `<section class="rabbit-entrance" aria-label="Jarvis"><div class="rabbit-signature" translate="no">JARVIS</div><div class="awakening-face" role="img" aria-label="Jarvis – Augen und Grinsen wachen auf"><img class="face-part eye-left" src="assets/face.png" alt="" width="1536" height="1024"><img class="face-part eye-right" src="assets/face.png" alt="" width="1536" height="1024"><img class="face-part waking-grin" src="assets/face.png" alt="" width="1536" height="1024"></div><a class="rabbit-enter" href="#/uebersicht" translate="no"><span>Enter the Rabbit hole</span><span aria-hidden="true">↗</span></a><div class="rabbit-wordmark" translate="no">AI WORKFORCE</div></section>`;}
 const entranceRender=render;render=()=>{entranceRender();const entering=location.hash==='#/start'||!location.hash;document.body.classList.toggle('is-entrance',entering);if(entering){$('#main').innerHTML=entrance();document.title='Enter the Rabbit hole · Jarvis';}};

 // Final PM usability pass: create, edit, resume and isolated product context.
 onProductActivated=()=>{ui.phase=null;ui.peek=null;pm.search='';pm.filter='Alle';pm.priority='Alle';};
 ensureProductTaskItem=()=>{const d=state.taskDraft;if(!d)return;const current=features.find(f=>f.id===d.itemId&&f.project===state.project);if(current)return;const f={id:'item-'+pm.serial++,project:state.project,category:'features',type:'Feature',name:d.title,description:d.text,priority:'P2',status:'Geplant',custom:true};features.push(f);d.itemId=f.id;};
 newProject=()=>back('Alle Produkte','projekte')+heading('Neues Produkt','Was möchtest du entwickeln?','Ein Name und ein erstes Ziel reichen für den Anfang.')+`<form class="form product-create-form" id="product-create"><label class="field">Produktname<input name="name" required maxlength="70" placeholder="Zum Beispiel: Mein Haushaltsbuch" autocomplete="off"></label><label class="field">Was soll dein Produkt ermöglichen?<textarea name="goal" required placeholder="Zum Beispiel: Ausgaben verstehen und monatlich Geld zurücklegen."></textarea></label><details><summary>Zielgruppe ergänzen · optional</summary><label class="field">Für wen entwickeln wir?<input name="audience" placeholder="Zum Beispiel: Menschen, die ihre Finanzen ordnen möchten."></label></details><details><summary>Projektordner · optional</summary><label class="field">Vorhandener Projektordner<input name="folder" placeholder="/projekte/mein-produkt"><small>Für die echte Umsetzung wird ein verbundenes Projektverzeichnis benötigt. Die Vorschau erstellt keine Dateien.</small></label></details><div class="action-row"><button class="button primary" type="submit">Produkt anlegen</button>${link('Abbrechen','projekte')}</div><p class="scope">Designvorschau: Das Produkt bleibt während dieser Sitzung verfügbar.</p></form>`;
 projectReady=id=>heading('Produkt angelegt',esc(project().name),'Du kannst dein Ziel jederzeit bearbeiten. Jetzt beschreiben wir die erste sinnvolle Funktion.')+`<section class="first-step"><div class="eyebrow">Dein nächster Schritt</div><h2>Was soll die erste Version können?</h2><p>${esc(productBrief().goal)}</p><div class="action-row">${button('Erstes Feature beschreiben','pm-new','button primary','data-category="features"')}${link('Erst mit dem Coach klären','jarvis/coach','button')}${link('Zur Produktübersicht →','projekt/'+id,'text-link')}</div><ol class="onboarding-steps"><li><strong>1 · Beschreiben</strong><span>Was soll für Nutzer möglich werden?</span></li><li><strong>2 · Prüfen</strong><span>Jarvis bereitet den Ablauf vor.</span></li><li><strong>3 · Freigeben</strong><span>Du entscheidest, wann es losgeht.</span></li></ol></section>`;
 function editProductDialog(){const p=project(),b=productBrief();modal('Produkt bearbeiten',`<form id="product-edit" data-id="${p.id}"><label class="field">Produktname<input name="name" required maxlength="70" value="${esc(p.name)}"></label><label class="field">Ziel dieser Version<textarea name="goal" required>${esc(b.goal)}</textarea></label><label class="field">Für wen entwickeln wir?<textarea name="audience">${esc(b.audience)}</textarea></label><details><summary>Problem & Erfolgskriterien</summary><label class="field">Welches Problem lösen wir?<textarea name="problem">${esc(b.problem)}</textarea></label><label class="field">Woran erkennen wir Erfolg?<textarea name="success">${esc(b.success)}</textarea></label></details><p class="scope">Ändert das Produktbriefing. Bestehende Aufträge und ihre Freigaben bleiben unverändert.</p><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Änderungen speichern</button></div></form>`);}
 const auditedOverview=overview;overview=()=>{const c=pmCounts(),p=project();if(state.scenario==='unavailable')return auditedOverview();const edit=button('Produkt bearbeiten','edit-product','button');if(!c.all.length&&!activeProjectRun())return heading('Produktübersicht',esc(p.name),'',edit)+briefStrip()+`<section class="first-step"><span class="eyebrow">Dein nächster Schritt</span><h2>Beschreibe die erste Funktion.</h2><p>Es ist noch keine Arbeit geplant. Beginne mit dem Ergebnis, das dein Produkt für Nutzer liefern soll.</p><div class="action-row">${button('Erstes Feature beschreiben','pm-new','button primary','data-category="features"')}${link('Mit dem Coach klären','jarvis/coach','button')}</div><ol class="onboarding-steps"><li><strong>Beschreiben</strong><span>Idee und gewünschtes Ergebnis</span></li><li><strong>Ablauf prüfen</strong><span>Arbeitsschritte und Zuständigkeiten</span></li><li><strong>Freigeben</strong><span>Bewusster Start der Umsetzung</span></li></ol></section>${state.taskDraft?draftBanner():''}<details class="empty-product-details"><summary>Planung, Produktzyklus & Workforce ansehen</summary><div class="action-row">${link('Roadmap','projekt/'+p.id+'/roadmap')}${link('Produktzyklus','produktzyklus/strategy')}${link('Workforce','harness/skelett')}</div></details>`;let html=auditedOverview().replace('<div class="action-row">',`<div class="action-row">${edit}`);return html.replace('<section class="product-cockpit">',(state.taskDraft?draftBanner():'')+'<section class="product-cockpit">');};
 function draftBanner(){return `<aside class="resume-draft"><div><span class="eyebrow">Dein Auftragsentwurf</span><strong>${esc(state.taskDraft?.title||'Noch ohne Titel')}</strong><small>In dieser Sitzung erhalten · noch nicht freigegeben</small></div>${link('Entwurf fortsetzen →','auftrag/neu','button primary')}</aside>`;}
 const auditedPortfolio=projectsPage;projectsPage=()=>auditedPortfolio().replaceAll('Produkt öffnen →','Weiterarbeiten →');
 const auditedShell=shell;shell=()=>{auditedShell();$('#topbar .top-left')?.insertAdjacentHTML('beforeend',link(icon('plus'),'projekt/neu','button new-product-shortcut').replace('<a ','<a aria-label="Neues Produkt anlegen" title="Neues Produkt anlegen" '));};
 const auditedRender=render;render=()=>{auditedRender();if((ui.chat||location.hash.startsWith('#/jarvis'))&&state.composerDraft){const input=$('#chat-input');if(input&&!input.value)input.value=state.composerDraft;}};
 document.addEventListener('input',e=>{const form=e.target.closest?.('form');if(form?.id==='new-task'){const d=new FormData(form);state.taskDraft={...state.taskDraft,title:d.get('title')||'',text:d.get('text')||'',evidence:d.get('evidence')||''};}if(e.target.id==='chat-input')state.composerDraft=e.target.value;});
 const auditedSend=sendChat;sendChat=text=>{state.composerDraft='';auditedSend(text);};
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el?.dataset.action==='edit-product')editProductDialog();});
 document.addEventListener('submit',e=>{const f=e.target;if(!['product-create','product-edit'].includes(f.id))return;e.preventDefault();const d=new FormData(f),read=k=>String(d.get(k)||'').trim(),name=read('name'),goal=read('goal');if(!name||!goal)return;if(f.id==='product-create'){let base=name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'produkt',id=base,n=2;while(state.projects.some(p=>p.id===id))id=base+'-'+n++;state.projects.push({id,name,description:goal,folder:read('folder')});briefs[id]={goal,audience:read('audience')||'Noch nicht festgelegt',problem:'Noch nicht beschrieben',success:'Erfolgskriterien gemeinsam mit dem Coach klären.'};storeWrite('jarvis-product-briefs',briefs);activateProduct(id);go('projekt/'+id+'/bereit');toast('Produkt angelegt. Beschreibe jetzt die erste Funktion.');}else{const p=state.projects.find(p=>p.id===f.dataset.id);if(!p)return;p.name=name;p.description=goal;briefs[p.id]={goal,audience:read('audience'),problem:read('problem'),success:read('success')};storeWrite('jarvis-product-briefs',briefs);closeModal();render();toast('Produkt aktualisiert. Bestehende Aufträge bleiben unverändert.');}});

 // Project-scoped technical understanding, evidence and code access.
 const techStore={},techViews={};
 const techData=()=>techStore[state.project]??={questions:[],issues:[],checks:{},repo:''};
 const architectureNodes=[['interface','Bedienoberfläche','Übersicht, Planung, Chat und Freigaben.','Liest Status; schreibt nur über validierte Aktionen.'],['orchestration','Orchestrierung','Ordnet Aufgaben Rollen zu und kontrolliert den Ablauf.','Serverzustand, Freigaben und Ausführungssperre bleiben maßgeblich.'],['workers','Worker & Werkzeuge','Claude Code, Codex, Skills und erlaubte Verbindungen.','Worker und tatsächlich beobachtetes Modell getrennt erfassen.'],['evidence','Projektwissen & Nachweise','Versionierte Dateien, Spezifikationen, Ergebnisse und Entscheidungen.','Jede Freigabe bezieht sich auf eine konkrete Version.']];
 const entities=[['product','Produkt',['ID','Ziel','Zielgruppe'],'Ein Produkt enthält viele Einträge.'],['item','Eintrag',['Produkt-ID','Typ / Priorität','Spezifikationsversion'],'Ein Eintrag kann mehrere Aufträge besitzen.'],['task','Auftrag & Ausführung',['Eintrag-ID','Rolle / Worker / Modell','Status / Ergebnis'],'Ausführungen liefern Nachweise für eine Entscheidung.'],['decision','Entscheidung & Nachweis',['Ausführungs-ID','Version / Quelle','Urteil / Begründung'],'Eine Entscheidung gilt für den geprüften Snapshot.']];
 const healthGroups={product:{title:'Produkt',checks:['Akzeptanzkriterien & Tests','Offene Fehler & Risiken','Architektur & Datenkonsistenz']},workforce:{title:'AI Workforce',checks:['Ausführung & Wiederaufnahme','Review & Nachweisqualität','Status & Modellbeobachtung']},harness:{title:'Harness',checks:['Freigaben & Berechtigungen','Hooks, Skills & MCPs','Konfiguration & Checkpoints']}};
 function healthResult(group){const checks=healthGroups[group].checks.map((_,i)=>techData().checks[group+'-'+i]),known=checks.filter(c=>c&&c.status!=='unknown'),failed=known.some(c=>c.status==='fail');return{known:known.length,total:checks.length,failed,score:known.length===checks.length?Math.round(known.reduce((s,c)=>s+({pass:1,warn:.5,fail:0}[c.status]),0)/checks.length*100):null};}
 function technicalNav(tab){return `<nav class="tabs">${[['architecture','Architektur'],['data','Datenmodell'],['code','Code & Änderungen'],['issues','Probleme & Fragen'],['health','Health & Nachweise']].map(([k,n])=>link(n,'projekt/'+state.project+'/technik/'+k,tab===k?'active':'')).join('')}</nav>`;}
 function technicalPage(tab='architecture'){if(!['architecture','data','code','issues','health'].includes(tab))tab='architecture';const data=techData(),selected=techViews[state.project]||'interface';let body='';if(tab==='architecture')body=`<p class="note">${isMain()?'Konzeptionelles Beispiel für AI Workforce · keine eingelesene Repository-Architektur.':'Architektur noch nicht eingelesen. Verbinde das Repository und lasse den Aufbau analysieren.'}</p>${isMain()?`<div class="architecture-map" role="group" aria-label="Architekturbausteine">${architectureNodes.map(([id,title,desc],i)=>`<button class="architecture-node ${selected===id?'selected':''}" data-action="inspect-architecture" data-id="${id}"><small>0${i+1}</small><strong>${title}</strong><span>${desc}</span></button>`).join('')}</div><div class="architecture-relations"><span>Oberfläche → Orchestrierung: Aufträge & Freigaben</span><span>Orchestrierung → Worker: kontrollierte Ausführung</span><span>Worker → Nachweise: Ergebnisse & Prüfbefunde</span><span>Nachweise → Oberfläche: aktueller Stand</span></div><section class="architecture-inspector"><span class="eyebrow">Ausgewählter Baustein</span><h2>${architectureNodes.find(n=>n[0]===selected)?.[1]||'Bedienoberfläche'}</h2><p>${architectureNodes.find(n=>n[0]===selected)?.[3]||''}</p>${button('Dazu eine Frage stellen','technical-question','button primary',`data-context="${selected}"`)} ${button('Problem festhalten','technical-issue','button',`data-context="${selected}"`)}</section>`:button('Architekturfrage festhalten','technical-question','button primary','data-context="architecture"')}`;else if(tab==='data')body=`<div class="note">Konzeptionelles Datenmodell · kein ausgelesenes Datenbankschema. Beziehungen und Felder müssen am echten Repository geprüft werden.</div>${isMain()?`<div class="entity-grid">${entities.map(([id,title,fields,rel])=>`<article class="entity-card"><h2>${title}</h2><ul>${fields.map(f=>`<li>${f}</li>`).join('')}</ul><p>${rel}</p>${button('Frage zum Modell','technical-question','button',`data-context="${id}"`)}</article>`).join('')}</div>`:empty('Datenmodell noch nicht verfügbar','Nach der Anbindung werden Entitäten, Beziehungen und Quellen hier sichtbar.',button('Frage zum Modell','technical-question','button','data-context="data"'))}`;else if(tab==='code')body=codePage();else if(tab==='health')body=healthPage();else body=`<div class="section-label"><h2>Offene Probleme</h2>${button('Problem festhalten','technical-issue','button primary','data-context="product"')}</div>${data.issues.length?data.issues.map((i,n)=>`<article class="technical-issue"><span class="tag">${esc(i.priority)} · ${esc(i.category)}</span><h3>${esc(i.title)}</h3><p>${esc(i.text)}</p><small>Quelle: ${esc(i.source)} · ${esc(i.context)}</small>${i.itemId?link('Im Arbeitsvorrat öffnen →','arbeit/'+i.itemId,'button'):button('Als Arbeit vorbereiten','issue-to-work','button',`data-index="${n}"`)}</article>`).join(''):'<p class="subtle">Noch keine technischen Befunde erfasst. Das ist kein Nachweis für Fehlerfreiheit.</p>'}<div class="section-label"><h2>Fragen zum Produkt</h2>${button('Frage stellen','technical-question','button','data-context="product"')}</div>${data.questions.map(q=>`<article class="technical-question"><span class="tag">Offen · keine KI-Antwort</span><h3>${esc(q.text)}</h3><small>${esc(q.context)}</small></article>`).join('')||'<p class="subtle">Stelle eine Frage zu Aufbau, Daten, Entscheidungen oder Problemen.</p>'}`;return back('Produktübersicht','projekt/'+state.project)+heading('Technischer Einblick',esc(project().name),'Aufbau verstehen, Änderungen nachvollziehen und Risiken prüfen.')+technicalNav(tab)+body+`<p class="scope">Designvorschau · Einträge und Bewertungen bleiben in dieser Sitzung. Keine Live-Analyse.</p>`;}
 function codePage(){const data=techData(),active=pmCounts().active[0];return `<section class="code-context"><div><span class="eyebrow">Produkt-Repository</span><h2>${data.repo?'Repository hinterlegt':'Noch nicht verbunden'}</h2><p>${data.repo?'Der Link öffnet dein Repository. Branch, Commit und Dateiänderungen werden noch nicht eingelesen.':'Der Prototyp kann dein lokales Produkt-Repository noch nicht lesen.'}</p>${data.repo?`<a class="button primary" href="${esc(data.repo)}" target="_blank" rel="noopener noreferrer">Repository öffnen ↗</a>`:''} ${button('Repository-Link hinterlegen','set-repository','button')}</div></section><div class="section-label"><h2>Gerade bearbeitet</h2></div><div class="note"><strong>${active?esc(active.name):'Keine aktive Entwicklung in diesem Produkt'}</strong><p>${active?'Dateiänderungen werden noch nicht beobachtet. Eine aktive Rolle ist kein Nachweis dafür, welche Datei sie gerade bearbeitet.':'Live-Dateiaktivität erscheint erst mit der echten Worker-Anbindung.'}</p>${active?link('Ausführung ansehen →',pmInfo(active).path,'text-link'):''}</div>${isMain()?`<details><summary>Zuletzt gemeldete Datei · Beispiel F35</summary><p><code>src/ui/workboard.js</code> · aus dem Beispielkontext, kein gelesener Dateiinhalt.</p>${link('Ergebnis & Nachweise ansehen →','ausfuehrung/build','button')}</details>`:''}<section class="reference-code"><div class="section-label"><div><span class="eyebrow">Tatsächlicher Code dieser Designreferenz</span><h2>Oberfläche im Detail</h2></div></div><p class="subtle">Diese Dateien gehören zum Designprototyp, nicht zum verbundenen Produkt.</p><div class="action-row">${[['experience.js','Interaktionen'],['style.css','Gestaltung'],['localization.js','Sprachen']].map(([file,n])=>button(n,'read-reference-code','button',`data-file="${file}"`)).join('')}</div><div id="reference-code-view" class="reference-code-view"><p class="subtle">Wähle eine Datei, um ihren aktuellen Inhalt schreibgeschützt anzusehen.</p></div></section>`;}
 function healthPage(){return `<div class="health-grid">${Object.entries(healthGroups).map(([key,g])=>{const r=healthResult(key);return `<article class="health-card"><span class="eyebrow">${g.title}</span><strong class="health-number ${r.score===null?'unknown':r.failed?'unhealthy':r.score<100?'warning':''}">${r.score===null?'—':r.score+' / 100'}</strong><h2>${r.failed?'Kritischer Befund':r.score===null?'Nicht vollständig bewertet':r.score===100?'Prüffelder erfüllt':'Handlungsbedarf'}</h2><p>${r.known} / ${r.total} <span>Prüffelder mit Nachweis</span></p><div class="health-checks">${g.checks.map((name,i)=>{const c=techData().checks[key+'-'+i];return `<div><strong>${name}</strong><span>${c?({pass:'Erfüllt',warn:'Eingeschränkt',fail:'Nicht erfüllt',unknown:'Nicht bewertet'}[c.status]):'Nicht bewertet'}</span>${c?`<small>${esc(c.source)} · ${esc(c.date)} · Manuell erfasst</small>`:''}${button('Bewertung erfassen','health-check','button',`data-key="${key+'-'+i}"`)}</div>`;}).join('')}</div></article>`;}).join('')}</div><details class="health-method"><summary>Wie entsteht die Bewertung?</summary><p>Manuelle Orientierung, keine automatische Qualitäts- oder Sicherheitsgarantie. Jedes Prüffeld benötigt einen Nachweis und einen Bezugsstand. Erfüllt zählt 1, eingeschränkt 0,5, nicht erfüllt 0. Die drei Felder sind gleich gewichtet. Eine Zahl erscheint erst, wenn alle drei bewertet sind. Ein negativer Befund bleibt unabhängig vom Mittelwert sichtbar.</p><p>Bewertungen gelten nur für den angegebenen Stand. Änderungen können sie veralten lassen; vor einer Freigabe erneut prüfen.</p></details>`;}
 const technicalProject=projectPage;projectPage=(id,tab)=>tab==='technik'?technicalPage(location.hash.split('/')[4]||'architecture'):technicalProject(id,tab);
 const technicalOverview=overview;overview=()=>{const html=technicalOverview();if(state.scenario==='unavailable')return html;return html.replace(button('Produkt bearbeiten','edit-product','button'),button('Produkt bearbeiten','edit-product','button')+link('Architektur & Code','projekt/'+state.project+'/technik/architecture','button'))+`<section class="technical-entry"><div><span class="eyebrow">Dein Produkt verstehen</span><h2>Was steckt dahinter?</h2><p>Architektur, Datenmodell, Code und überprüfbare Befunde.</p></div><div class="action-row">${link('Architektur & Daten','projekt/'+state.project+'/technik/architecture','button')}${link('Code & Änderungen','projekt/'+state.project+'/technik/code','button')}${link('Health & Nachweise','projekt/'+state.project+'/technik/health','button')}</div></section>`;};
 function techQuestion(context){modal('Frage zum Produkt',`<form id="technical-question-form" data-context="${esc(context)}"><p class="subtle">${esc(project().name)} · ${esc(context)}</p><label class="field">Was möchtest du verstehen?<textarea name="question" required placeholder="Warum ist das so aufgebaut? Welche Alternativen gibt es?"></textarea></label><p class="scope">Wird als offene Frage erfasst und im Product Coach vorbereitet. Ohne echte KI-Anbindung wird keine Antwort erzeugt.</p><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Frage vorbereiten</button></div></form>`);}
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case'inspect-architecture':techViews[state.project]=el.dataset.id;render();break;case'technical-question':techQuestion(el.dataset.context);break;case'technical-issue':modal('Technisches Problem festhalten',`<form id="technical-issue-form" data-context="${esc(el.dataset.context)}"><label class="field">Titel<input name="title" required></label><label class="field">Problem & Auswirkung<textarea name="text" required></textarea></label><label class="field">Quelle / betroffener Stand<input name="source" required placeholder="Datei, Commit, Testbericht oder Beobachtung"></label><div class="grid cols-2"><label class="field">Bereich<select name="category"><option value="bugs">Bug</option><option value="improvements">Harness Improvement</option><option value="features">Architekturänderung</option></select></label><label class="field">Priorität<select name="priority"><option>P0</option><option>P1</option><option selected>P2</option><option>P3</option></select></label></div><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Problem speichern</button></div></form>`);break;case'issue-to-work':{const issue=techData().issues[Number(el.dataset.index)];if(!issue)return;if(!issue.itemId){const f={id:'item-'+pm.serial++,project:state.project,category:issue.category,type:pmCategories[issue.category].singular,name:issue.title,description:issue.text+'\n\nQuelle: '+issue.source,priority:issue.priority,custom:true,status:'Geplant'};features.push(f);issue.itemId=f.id;}go('arbeit/'+issue.itemId);break;}case'set-repository':modal('Repository-Link hinterlegen',`<form id="repository-link-form"><label class="field">HTTPS-Adresse deines Repositorys<input name="url" type="url" required value="${esc(techData().repo)}" placeholder="https://…"></label><p class="scope">Speichert nur den Link. Keine Zugangsdaten, kein automatischer Repository-Zugriff.</p><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Speichern</button></div></form>`);break;case'health-check':{const key=el.dataset.key,c=techData().checks[key];modal('Nachweisbasierte Bewertung',`<form id="health-check-form" data-key="${esc(key)}"><label class="field">Prüfergebnis<select name="status">${[['unknown','Nicht bewertet'],['pass','Erfüllt'],['warn','Eingeschränkt'],['fail','Nicht erfüllt']].map(([v,n])=>`<option value="${v}" ${c?.status===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Nachweis und Bezugsstand<textarea name="source" required placeholder="Zum Beispiel: Testbericht für Commit …; geprüft am …">${esc(c?.source||'')}</textarea></label><p class="scope">Manuelle Bewertung. Kein automatischer Test und keine Freigabe.</p><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Bewertung speichern</button></div></form>`);break;}case'read-reference-code':{const allowed=['experience.js','style.css','localization.js'],file=el.dataset.file;if(!allowed.includes(file))return;const target=$('#reference-code-view');target.innerHTML='<p>Lädt …</p>';try{const response=await fetch(file);if(!response.ok)throw Error('Unavailable');const source=await response.text();if(!target.isConnected)return;target.innerHTML=`<div class="code-file-heading"><code>${file}</code><a href="${file}" download class="button">Datei herunterladen</a></div><pre tabindex="0" aria-label="Quellcode ${file}"><code translate="no">${esc(source)}</code></pre>`;}catch{target.innerHTML='<p class="note">Datei konnte nicht geladen werden. Nutze das vollständige Designpaket.</p>';}break;}}});
 document.addEventListener('submit',e=>{const form=e.target;if(!['technical-question-form','technical-issue-form','repository-link-form','health-check-form'].includes(form.id))return;e.preventDefault();const d=new FormData(form),read=k=>String(d.get(k)||'').trim(),data=techData();if(form.id==='technical-question-form'){const q=read('question');if(!q)return;data.questions.push({text:q,context:form.dataset.context});state.mode='coach';state.composerDraft='Produkt: '+project().name+'\nKontext: '+form.dataset.context+'\nFrage: '+q;ui.chat=true;closeModal();go('projekt/'+state.project+'/technik/issues');render();return;}if(form.id==='technical-issue-form'){if(!read('title')||!read('text')||!read('source')||!pmCategories[read('category')])return;data.issues.push({title:read('title'),text:read('text'),source:read('source'),category:read('category'),priority:read('priority'),context:form.dataset.context});closeModal();go('projekt/'+state.project+'/technik/issues');render();return;}if(form.id==='repository-link-form'){try{const u=new URL(read('url'));if(u.protocol!=='https:'||u.username||u.password)throw Error();data.repo=u.href;}catch{toast('Bitte einen HTTPS-Link ohne Zugangsdaten eingeben.');return;}}else{const key=form.dataset.key;if(!/^(product|workforce|harness)-[0-2]$/.test(key)||!['unknown','pass','warn','fail'].includes(read('status'))||!read('source'))return;data.checks[key]={status:read('status'),source:read('source'),date:new Date().toISOString().slice(0,10)};}closeModal();render();});

 // Three product phases and a project-scoped knowledge graph.
 const productPhases=[{id:'ideate',title:'Ideate',caption:'Die richtige Idee finden',steps:[['strategy','Strategie verstehen'],['discover','Markt & Nutzer verstehen'],['capture','Ideen & Feedback sammeln']]},{id:'plan',title:'Plan',caption:'Die Lösung durchdenken',steps:[['explore','Lösungen vertiefen'],['plan','Business- & Umsetzungsplan'],['architecture','Technik vertiefen']]},{id:'deliver',title:'Deliver',caption:'Umsetzen und ausliefern',steps:[['deliver','Entwickeln'],['test','Testen'],['launch','Deployen']]}];
 const cycleBeforeGrouping=cyclePage;cyclePage=(route='ideate')=>{const group=productPhases.find(p=>p.id===route)||productPhases.find(p=>p.steps.some(s=>s[0]===route))||productPhases[0];const candidate=location.hash.split('/')[3]||(!productPhases.some(p=>p.id===route)?route:null);const step=group.steps.find(s=>s[0]===candidate)||group.steps[0];let content;if(step[0]==='architecture')content=`<section class="cycle-content"><h2>Technik vertiefen</h2><p>Architekturentscheidungen, Schnittstellen und Datenmodell vor der Umsetzung klären.</p><div class="action-row">${link('Architektur erkunden','projekt/'+state.project+'/technik/architecture','button primary')}${link('Datenmodell ansehen','projekt/'+state.project+'/technik/data','button')}${link('Architecture.md','harness/datei/architecture','button')}</div>${button('Frage zur Architektur','technical-question','button','data-context="architecture"')}</section>`;else if(step[0]==='test')content=`<section class="cycle-content"><h2>Testen</h2><p>Akzeptanzkriterien, Testnachweise und Review prüfen. Ein erfolgreicher Lauf ist noch keine menschliche Abnahme.</p><div class="action-row">${link('Ergebnisse & Entscheidungen','entscheidungen','button primary')}${link('Qualität & Nachweise','projekt/'+state.project+'/technik/health','button')}${link('Offene Bugs','arbeit/bugs','button')}</div><p class="scope">Keine neuen Tests ausgeführt. Echte Testberichte werden später angebunden.</p></section>`;else{const html=cycleBeforeGrouping(step[0]);content=html.slice(html.indexOf('<section class="cycle-content">'));}return heading('Produktmanagement',esc(project().name),'Ideate · Plan · Deliver')+`<nav class="product-phases" aria-label="Produktphasen">${productPhases.map((p,i)=>`<a href="#/produktzyklus/${p.id}/${p.steps[0][0]}" class="product-phase ${p.id===group.id?'active':''}" ${p.id===group.id?'aria-current="step"':''}><span class="phase-orbit"><small>0${i+1}</small><strong>${p.title}</strong></span><span>${p.caption}</span></a>`).join('')}</nav><nav class="phase-substeps" aria-label="Schritte in ${group.title}">${group.steps.map(([id,name],i)=>link(`<small>${i+1}</small>${name}`,'produktzyklus/'+group.id+'/'+id,id===step[0]?'active':'')).join('')}</nav>${step[0]==='plan'?'<p class="note">Business-Ziele, Annahmen, Nutzen und Umsetzungsplan hier zusammenführen. Notizen können mit Features verbunden werden.</p>':''}${content}`;};
 const brainStore={},documentDrafts={};let brainSelected='project',brainFilter='all',brainSearch='',brainZoom=1;
 function brainData(){if(brainStore[state.project])return brainStore[state.project];const nodes=[{id:'project',name:project().name,type:'Produkt',text:productBrief().goal,source:'Aktuelles Produktbriefing',path:'projekt/'+state.project},{id:'strategy',name:'Vision & Nutzer',type:'Wissen',text:productBrief().audience,source:'Produktbriefing · Vorschau',path:'produktzyklus/ideate/strategy'},{id:'architecture',name:'Architecture.md',type:'Dokument',text:'Architektur des Produkts, Schnittstellen und Entscheidungen.',source:'Datei noch nicht eingelesen',path:'harness/datei/architecture'},{id:'claude',name:'Claude.md',type:'Dokument',text:'Projektbezogene Arbeitsanweisungen für Claude.',source:'Datei noch nicht eingelesen',path:'harness/datei/claude'},{id:'code',name:'Code & Änderungen',type:'Code',text:'Repository, beobachtete Änderungen und Quellen.',source:'Noch keine Live-Repository-Analyse',path:'projekt/'+state.project+'/technik/code'},{id:'decisions',name:'Entscheidungen',type:'Entscheidung',text:'Freigaben und ihre Begründung nachvollziehen.',source:'Beispielzustand · keine Live-Daten',path:'entscheidungen'},{id:'research',name:'Nutzerwissen',type:'Wissen',text:'Interviews, Annahmen und Feedback miteinander verbinden.',source:'Konzeptioneller Knoten',path:'produktzyklus/ideate/discover'},{id:'data',name:'Datenmodell',type:'Code',text:'Entitäten und ihre Beziehungen.',source:'Konzeptionell · nicht ausgelesen',path:'projekt/'+state.project+'/technik/data'}];const edges=[['project','strategy','verfolgt'],['project','architecture','ist beschrieben in'],['architecture','code','strukturiert'],['architecture','data','definiert'],['claude','code','leitet Arbeit an'],['decisions','architecture','begründet'],['research','strategy','informiert'],['project','claude','verwendet'],['project','decisions','hat']].map(([from,to,label])=>({from,to,label}));return brainStore[state.project]={nodes,edges,serial:1};}
 const brainTypes=['Produkt','Wissen','Code','Entscheidung','Dokument'];
 function brainPositions(nodes){return nodes.map((n,i)=>{if(i===0)return{x:440,y:300};const a=(i-1)*2*Math.PI/Math.max(nodes.length-1,7)-Math.PI/2;return{x:440+330*Math.cos(a),y:300+225*Math.sin(a)};});}
 function brainPage(){const data=brainData(),selected=data.nodes.find(n=>n.id===brainSelected)||data.nodes[0];brainSelected=selected.id;const positions=brainPositions(data.nodes),visible=n=>(brainFilter==='all'||n.type===brainFilter)&&(!brainSearch||(n.name+' '+n.text).toLowerCase().includes(brainSearch.toLowerCase())),neighbors=data.edges.filter(e=>e.from===selected.id||e.to===selected.id);return heading('Brain',esc(project().name),'Wissen, Code und Entscheidungen im Zusammenhang.',button('Wissen hinzufügen','brain-add','button primary'))+`<div class="brain-toolbar"><label class="sr-only" for="brain-search">Wissen durchsuchen</label><input id="brain-search" placeholder="Knoten durchsuchen …" value="${esc(brainSearch)}"><select id="brain-filter" aria-label="Knotentyp"><option value="all">Alle Typen</option>${brainTypes.map(t=>`<option value="${t}" ${brainFilter===t?'selected':''}>${t}</option>`).join('')}</select>${button('−','brain-zoom-out','icon-button','aria-label="Verkleinern"')}<span>${Math.round(brainZoom*100)} %</span>${button('+','brain-zoom-in','icon-button','aria-label="Vergrößern"')}${button('Zurücksetzen','brain-reset','button')}</div><div class="brain-layout"><div><div class="brain-canvas-scroll" tabindex="0" aria-label="Wissensgraph, horizontal und vertikal scrollbar"><div class="brain-size" style="width:${880*brainZoom}px;height:${600*brainZoom}px"><div class="brain-canvas" style="transform:scale(${brainZoom})"><svg viewBox="0 0 880 600" aria-hidden="true">${data.edges.map(e=>{const a=data.nodes.findIndex(n=>n.id===e.from),b=data.nodes.findIndex(n=>n.id===e.to);if(a<0||b<0)return'';return `<line class="${e.from===selected.id||e.to===selected.id?'selected':''}" x1="${positions[a].x}" y1="${positions[a].y}" x2="${positions[b].x}" y2="${positions[b].y}"/>`;}).join('')}</svg>${data.nodes.map((n,i)=>`<button class="brain-node type-${brainTypes.indexOf(n.type)} ${n.id===selected.id?'selected':''} ${visible(n)?'':'muted-node'}" style="left:${positions[i].x}px;top:${positions[i].y}px" data-action="brain-select" data-id="${n.id}" aria-pressed="${n.id===selected.id}" aria-label="${esc(n.name+' · '+n.type)}"><span class="brain-dot"></span><strong>${esc(n.name)}</strong></button>`).join('')}</div></div></div><p class="scope">Veranschaulichung · kein automatisch extrahierter Codegraph. Graphify / Oblivion: noch nicht angebunden.</p><details><summary>Alle Knoten als Liste</summary><div class="brain-node-list">${data.nodes.filter(visible).map(n=>button(esc(n.name),'brain-select','button',`data-id="${n.id}"`)).join('')||'<p>Keine Treffer.</p>'}</div></details></div><aside class="brain-inspector"><span class="eyebrow">${esc(selected.type)}</span><h2>${esc(selected.name)}</h2><p>${esc(selected.text)}</p><small>${esc(selected.source)}</small>${selected.path?link('Quelle / Bereich öffnen →',selected.path,'text-link'):''}<div class="action-row">${button('Bearbeiten','brain-edit','button',`data-id="${selected.id}"`)}${button('Verknüpfen','brain-connect','button',`data-id="${selected.id}"`)}${button('Challengen','brain-challenge','button',`data-id="${selected.id}"`)}</div><h3>Verbindungen</h3>${neighbors.map(e=>{const n=data.nodes.find(n=>n.id===(e.from===selected.id?e.to:e.from));return `<div class="brain-relation"><small>${e.from===selected.id?'→':'←'} ${esc(e.label)}</small>${button(esc(n?.name||''),'brain-select','text-link',`data-id="${n?.id}"`)}${button('×','brain-unlink','icon-button',`data-index="${data.edges.indexOf(e)}" aria-label="Verbindung entfernen"`)}</div>`;}).join('')||'<p class="subtle">Noch keine Verbindungen.</p>'}</aside></div>`;}
 for(const [id,title,desc] of [['architecture','Architecture.md','Architektur, Systemgrenzen, Schnittstellen und technische Entscheidungen.'],['claude','Claude.md','Projektbezogene Anweisungen, Arbeitsweise und Grenzen für Claude.']])modules.push({id,title,tag:'Projektdokument',desc,input:'Versionierte Projektdatei',output:'Nachvollziehbare Arbeitsgrundlage',rule:'Entwürfe ändern noch keine echte Projektdatei. Der tatsächliche Dateiname muss im Repository geprüft werden.',endpoint:'Projektbezogener Dateiinhalt, Version und kontrollierte Änderungsaktion erforderlich',path:'harness/datei/'+id,items:[],source:'Noch nicht eingelesen',symbol:'▤'});
 const documentSkeleton=skeleton;skeleton=()=>documentSkeleton().replace(/<section id="module-(architecture|claude)"([^>]*)>/g,(match,id)=>match+link('Dokument öffnen & bearbeiten →','harness/datei/'+id,'button primary'))+`<section class="harness-documents"><div class="section-label"><h2>Projektdokumente erkunden</h2></div><div class="grid cols-2">${['architecture','claude'].map(id=>`<article class="panel"><h3>${id==='architecture'?'Architecture.md':'Claude.md'}</h3><p>Inhalt ansehen, als Entwurf bearbeiten und kritisch prüfen lassen.</p>${link('Dokument öffnen →','harness/datei/'+id,'button primary')}</article>`).join('')}</div></section>`;
 function documentPage(id){if(!['architecture','claude'].includes(id))return notFound();const name=id==='architecture'?'Architecture.md':'Claude.md',d=documentDrafts[state.project]?.[id];return back('Harness','harness/skelett')+heading('Projektdokument · '+esc(project().name),name,'Erkunden, bearbeiten und kritisch hinterfragen.')+`<div class="note">${d?'Lokaler Sitzungsentwurf · noch nicht in die Projektdatei geschrieben.':'Originaldatei noch nicht eingelesen. Füge den Inhalt ein, um einen Entwurf zu prüfen.'} Der tatsächliche Dateiname und seine Groß-/Kleinschreibung werden später im Repository geprüft.</div><div class="document-layout"><form id="project-document" data-id="${id}"><label class="field">Dokumentinhalt<textarea class="document-editor" name="content" spellcheck="false" required placeholder="# ${name}\n\nInhalt der Projektdatei einfügen …">${esc(d?.content||'')}</textarea></label><label class="field">Quelle / Bezugsstand<input name="source" required value="${esc(d?.source||'')}" placeholder="Dateipfad und Commit oder eigene Entwurfsnotiz"></label><div class="action-row"><button type="submit" class="button primary">Entwurf speichern</button>${button('Challengen lassen','challenge-document','button',`data-id="${id}"`)}</div></form><aside class="summary"><h3>Prüffragen</h3><ul>${(id==='architecture'?['Sind Verantwortlichkeiten und Schnittstellen eindeutig?','Wo entstehen unnötige Abhängigkeiten?','Passen Datenmodell und Qualitätsanforderungen zusammen?']:['Sind Anweisungen eindeutig und widerspruchsfrei?','Bleiben Projektgrenzen und Freigaben erhalten?','Welche Regeln sind veraltet oder unbelegt?']).map(t=>`<li>${t}</li>`).join('')}</ul><p class="scope">Die Frage wird im Coach vorbereitet. Keine automatische Analyse oder Dateiänderung.</p>${link('Im Brain ansehen →','brain','text-link')}</aside></div>`;}
 function prepareBrainChallenge(name,text,source){state.mode='coach';state.composerDraft='Produkt: '+project().name+'\nPrüfe kritisch: '+name+'\nQuelle: '+source+'\n\n'+text+'\n\nBenenne Widersprüche, Risiken und offene Fragen. Trenne Belege von Annahmen und schlage konkrete Verbesserungen vor.';ui.chat=true;render();}
 function brainEdit(id){const n=brainData().nodes.find(n=>n.id===id);modal(n?'Wissen bearbeiten':'Wissen hinzufügen',`<form id="brain-node-form" data-id="${n?.id||''}"><label class="field">Titel<input name="name" required value="${esc(n?.name||'')}"></label><label class="field">Typ<select name="type">${brainTypes.map(t=>`<option value="${t}" ${t===(n?.type||'Wissen')?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Inhalt<textarea name="text" required>${esc(n?.text||'')}</textarea></label><label class="field">Quelle<input name="source" required value="${esc(n?.source||'Eigene Notiz')}"></label><p class="scope">Bearbeitet den Wissensknoten in der Vorschau, nicht die Quelldatei.</p><div class="dialog-actions">${button('Abbrechen','close-modal')}<button type="submit" class="button primary">Speichern</button></div></form>`);}
 const beforeBrainActivation=onProductActivated;onProductActivated=()=>{beforeBrainActivation();brainSelected='project';brainSearch='';brainFilter='all';brainZoom=1;};
 const brainShell=shell;shell=()=>{brainShell();$('#sidebar nav')?.insertAdjacentHTML('beforeend',link(icon('spark')+'Brain','brain','').replace('<a ','<a data-nav="brain" '));};
 const brainRender=render;render=()=>{brainRender();if(location.hash.startsWith('#/brain')){$('#main').innerHTML=brainPage();document.title='Brain · '+project().name;$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='brain'));}if(location.hash.startsWith('#/harness/datei/'))$('#main').innerHTML=documentPage(location.hash.split('/')[3]);window.JarvisI18n?.translate();};
 document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const data=brainData(),n=data.nodes.find(n=>n.id===el.dataset.id);switch(el.dataset.action){case'brain-select':brainSelected=el.dataset.id;render();break;case'brain-add':brainEdit();break;case'brain-edit':brainEdit(el.dataset.id);break;case'brain-zoom-in':brainZoom=Math.min(1.6,brainZoom+.2);render();break;case'brain-zoom-out':brainZoom=Math.max(.6,brainZoom-.2);render();break;case'brain-reset':brainZoom=1;brainSearch='';brainFilter='all';render();break;case'brain-unlink':{const i=Number(el.dataset.index);if(Number.isInteger(i)&&i>=0&&i<data.edges.length){data.edges.splice(i,1);render();}break;}case'brain-challenge':if(n)prepareBrainChallenge(n.name,n.text,n.source);break;case'brain-connect':if(n)modal('Wissen verbinden',`<form id="brain-edge-form" data-from="${n.id}"><p>${esc(n.name)}</p><label class="field">Verbindung zu<select name="to">${data.nodes.filter(x=>x.id!==n.id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">Beziehung<input name="label" required placeholder="Zum Beispiel: begründet, verwendet, hängt ab von"></label><div class="dialog-actions">${button('Abbrechen','close-modal')}<button type="submit" class="button primary">Verbinden</button></div></form>`);break;case'challenge-document':{const form=$('#project-document'),d=new FormData(form),content=String(d.get('content')||'').trim();if(!content){toast('Füge zuerst den Dokumentinhalt ein.');return;}(documentDrafts[state.project]??={})[el.dataset.id]={content,source:String(d.get('source')||'Ungespeicherter Entwurf')};prepareBrainChallenge(el.dataset.id==='architecture'?'Architecture.md':'Claude.md',content,String(d.get('source')||'Ungespeicherter Entwurf'));break;}}});
 document.addEventListener('change',e=>{if(e.target.id==='brain-filter'){brainFilter=e.target.value;render();}});
 document.addEventListener('input',e=>{if(e.target.id==='brain-search'){const start=e.target.selectionStart;brainSearch=e.target.value;render();const input=$('#brain-search');input?.focus();input?.setSelectionRange?.(start,start);}});
 document.addEventListener('submit',e=>{const f=e.target;if(!['brain-node-form','brain-edge-form','project-document'].includes(f.id))return;e.preventDefault();const d=new FormData(f),read=k=>String(d.get(k)||'').trim(),data=brainData();if(f.id==='brain-node-form'){if(!read('name')||!read('text')||!read('source')||!brainTypes.includes(read('type')))return;let n=data.nodes.find(n=>n.id===f.dataset.id);if(!n){n={id:'knowledge-'+data.serial++};data.nodes.push(n);}Object.assign(n,{name:read('name'),text:read('text'),type:read('type'),source:read('source')});brainSelected=n.id;closeModal();render();}else if(f.id==='brain-edge-form'){const from=f.dataset.from,to=read('to'),label=read('label');if(from===to||!label||!data.nodes.some(n=>n.id===from)||!data.nodes.some(n=>n.id===to))return;if(!data.edges.some(x=>x.from===from&&x.to===to&&x.label===label))data.edges.push({from,to,label});closeModal();render();}else{const id=f.dataset.id;if(!['architecture','claude'].includes(id)||!read('content')||!read('source'))return;(documentDrafts[state.project]??={})[id]={content:read('content'),source:read('source')};const n=data.nodes.find(n=>n.id===id);if(n){n.text=read('content');n.source='Sitzungsentwurf · '+read('source');}render();toast('Dokumententwurf gespeichert. Originaldatei unverändert.');}});

 if(!location.hash)history.replaceState(null,'','#/start');
 applyTheme();render();
